// task init: creates .task/ and registers the project for the task app-module.
import { ConfigDir } from '@wadeck-app/shared-cli';
import { describeError, registerInitializedProject } from '@wadeck-app/task-service';
import * as fs from 'node:fs';
import * as path from 'node:path';

import type { CommandResult } from '../cli/output.js';

const PROJECT_CONFIG_TEMPLATE = `# Task configuration for this project
# Generated by: task init

statuses:
  - backlog
  - in-progress
  - name: done
    terminal: true

# fields:
#   - name: component
#     type: string
#     required: false

# defaults:
#   priority: medium

# hooks:
#   onTaskCreated: ""
#   onStatusChange: ""
`;

/**
 * Records the project in <config dir>/projects.json so the task app-module can find it. Never fails the command:
 * the project is initialized either way, so a registry problem is only a warning with its fix.
 */
function registerProjectOrWarn(projectDir: string): void {
	try {
		registerInitializedProject(ConfigDir.get('task'), projectDir);
	} catch (error) {
		const { message, hint } = describeError(error);
		process.stderr.write(
			`[task] warning: could not register this project for the task app-module: ${message}${hint ? ` (${hint})` : ''}\n`
		);
	}
}

export function runInit(projectDir: string): CommandResult {
	const taskDir = path.join(projectDir, '.task');
	if (fs.existsSync(taskDir)) {
		// Re-running init is how an already initialized project gets registered.
		registerProjectOrWarn(projectDir);
		return { exitCode: 0, output: 'Project already initialized.' };
	}
	fs.mkdirSync(path.join(taskDir, 'tasks'), { recursive: true });
	fs.writeFileSync(path.join(taskDir, 'config.yml'), PROJECT_CONFIG_TEMPLATE, 'utf8');
	registerProjectOrWarn(projectDir);
	return { exitCode: 0, output: `Initialized task project in ${taskDir}` };
}
